css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .lin-fila{display: grid; grid-template-columns: 1fr 60px; gap: 10px; padding: 2px 10px; border: 1.2px solid var(--bosque); border-radius: 6px; margin-bottom: 2px; align-items: center;}
.mz .lin-texto{font-size: 14px; font-weight: 600;}
.mz .lin-texto .hueco{display: inline-block; min-width: 30px; border-bottom: 1.5px solid var(--bosque); margin: 0 4px;}
.mz .lin-caja{border: 1.5px solid var(--bosque); border-radius: 6px; height: 22px;}
.mz .unir-tabla{display: grid; grid-template-columns: 65px 1fr 140px; gap: 4px; margin-bottom: 2px; align-items: center;}
.mz .unir-num{font-size: 16px; font-weight: 700; text-align: center; border: 1.5px solid var(--bosque); border-radius: 6px; padding: 3px 0; font-family: sans-serif;}
.mz .unir-palabra{font-size: 13.5px; font-weight: 500; text-align: center; border: 1.5px solid var(--bosque); border-radius: 6px; padding: 4px 0;}
.mz .fila-letras{display: flex; gap: 5px; flex-wrap: nowrap; margin-bottom: 4px;}
.mz .fila-letras .caja-letra{width: 48px; height: 36px; border: 1.5px solid var(--bosque); border-radius: 6px; display: flex; align-items: center; justify-content: center; font-size: 18px; font-weight: 700; font-family: sans-serif; flex-shrink: 0;}
.mz .frase-fila{padding: 3px 12px; border: 1.2px solid var(--bosque); border-radius: 6px; margin-bottom: 2px; font-size: 14px; font-weight: 600; line-height: 1.4;}
.mz .frase-fila .hueco-grande{display: inline-block; min-width: 130px; border-bottom: 1.5px solid var(--bosque); margin: 0 6px; height: 20px; vertical-align: middle;}
.mz .frase-fila{line-height: 1.875 !important;}
